const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.chart}"/></svg>`;
const info = (text) => `<svg class="info-dot" viewBox="0 0 12 12" role="img" aria-label="${escapeHTML(text)}"><title>${escapeHTML(text)}</title><circle cx="6" cy="6" r="4.5"/><path d="M6 5.5v3 M6 3.5v.7"/></svg>`;
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const num = (value, digits=0) => !Number.isFinite(value) ? '—' : new Intl.NumberFormat('en-IN', {minimumFractionDigits:digits,maximumFractionDigits:digits}).format(value);
const money = (value, signed=false, digits=0) => value === null || value === undefined || Number.isNaN(value) ? '—' : !Number.isFinite(value) ? 'Unlimited' : `${value < -.5 ? '−' : signed && value > .5 ? '+' : ''}₹${num(Math.abs(value) < .5 ? 0 : Math.abs(value),digits)}`;
const clamp = (value,min,max) => Math.min(max,Math.max(min,value));
const uid = () => globalThis.crypto?.randomUUID?.() || `position-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const $ = (selector,root=document) => root.querySelector(selector);
const $$ = (selector,root=document) => [...root.querySelectorAll(selector)];
const WORKSPACE_KEY = 'folio.workspace.v1';
let library = [];
let storageError = '';
let pendingRecovery = null;
try { library = readPositions(); } catch(error) { storageError = error.message; }

const live = {client:null,busy:false,error:'',marketStatus:'unknown',quotes:{},receivedAt:null,valuationAt:new Date().toISOString(),generation:0,controller:null,connectAttempt:0,quoteRequest:0};
setDataMode('live');
const state = {
  view: ['builder','positions','chain','learn'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'builder',
  marketSymbol:'NIFTY', expiry:'', name:'Untitled strategy', preset:null,
  legs:[], multiplier:1, rate:.06,
  tab:'payoff', tableMode:'outcomes', filter:'All', search:'', positionId:null, notes:'', dirty:false,
  scenario:{spot:MARKETS[0].spot,days:0,iv:0}
};
try {
  const workspace = JSON.parse(localStorage.getItem(WORKSPACE_KEY) || 'null');
  if(workspace) {
    const saved = validateWorkspace(workspace);
    setDataMode(saved.dataMode === 'live' ? 'live' : 'demo');
    Object.assign(state,{marketSymbol:saved.marketSymbol,expiry:saved.expiry,name:saved.name,legs:saved.legs,rate:saved.rate??.06,notes:saved.notes||'',preset:workspace.preset||null,positionId:workspace.positionId||null});
    state.scenario.spot = market().spot;
  }
} catch { /* The saved library is independent of a disposable workspace draft. */ }

function market(){return MARKETS.find(entry=>entry.symbol===state.marketSymbol)||MARKETS[0];}
function legs(){return state.legs.map(leg=>({...leg,lots:leg.lots*state.multiplier,...(Number.isFinite(leg.quantityUnits)?{quantityUnits:leg.quantityUnits*state.multiplier}:{})}));}
function valuationDate(){return getDataMode()==='demo'?DEMO_DATE:live.valuationAt;}
function expiredUnsettled(){return getDataMode()==='live'&&state.legs.some(l=>l.enabled&&Date.parse(l.expiresAt||l.expiry+'T10:00:00Z')<=Date.parse(valuationDate())&&!Number.isFinite(l.settlementPrice));}
function modelAvailable(){if(getDataMode()==='live'){const stamp=Date.parse(market().asOf||'');if(!live.client||live.error||!Number.isFinite(stamp)||(live.marketStatus!=='closed'&&Date.now()-stamp>90000))return false;}return Number.isFinite(market().spot)&&state.legs.filter(l=>l.enabled).every(l=>Number.isFinite(l.iv))&&!expiredUnsettled();}
function analysis(){
  const active=legs(),spot=Number.isFinite(market().spot)?market().spot:(active[0]?.strike||1);
  const result=analyzeStrategy(active,spot,market().lotSize||1,market().iv||14.2,state.rate,valuationDate());
  if(!modelAvailable()){for(const key of ['pop','delta','gamma','theta','vega','rho'])result[key]=null;if(result.mixedExpiry){result.maxProfit=null;result.maxLoss=null;result.breakevens=[];}}
  return result;
}
function snapshot(){return {id:state.positionId||uid(),name:state.name.trim()||'Untitled strategy',marketSymbol:state.marketSymbol,expiry:state.expiry,legs:legs(),notes:state.notes,rate:state.rate,dataMode:getDataMode(),baseDate:valuationDate(),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};}
function persistWorkspace(){
  try{localStorage.setItem(WORKSPACE_KEY,JSON.stringify({...snapshot(),preset:state.preset,positionId:state.positionId}));}catch{/* A private browsing session can still use the calculator. */}
}
function markDirty(){state.dirty=true;persistWorkspace();}
function targetDays(){const active=state.legs.filter(leg=>leg.enabled);return active.length?Math.min(...active.map(leg=>daysToExpiry(leg.expiry,valuationDate()))):(state.expiry?daysToExpiry(state.expiry,valuationDate()):0);}
function targetPayoff(spot){return modelAvailable()&&Number.isFinite(spot)?scenarioPayoff(legs(),spot,state.scenario.days,state.scenario.iv,market().lotSize||1,state.rate,valuationDate()):NaN;}
function terminalPayoff(spot,a=analysis()){return a.mixedExpiry?scenarioPayoff(legs(),spot,a.daysToExpiry,0,market().lotSize||1,state.rate,valuationDate()):expiryPayoff(legs(),spot,market().lotSize||1);}
function expiryOptions(selected,short=false){const items=[...EXPIRIES];if(!items.length&&!selected)return '<option value="">Connect to load expiries</option>';if(selected&&!items.some(e=>e.value===selected))items.push({value:selected,label:formatDate(selected),short:formatDate(selected)});return items.map(e=>`<option value="${escapeHTML(e.value)}" ${e.value===selected?'selected':''}>${escapeHTML(short?e.short:e.label)}</option>`).join('');}
function formatDate(value,withYear=true){return new Date(value+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',...(withYear?{year:'numeric'}:{})});}
function sparkline(index=0){if(getDataMode()==='live')return '';const sets=['0,20 7,17 14,20 20,12 27,14 33,7 40,9 47,4 53,7 63,1','0,20 6,14 13,17 20,10 27,15 34,9 41,11 48,4 55,7 63,2','0,21 9,15 16,18 25,13 32,14 38,7 46,9 53,3 63,1'];return `<svg class="sparkline" viewBox="0 0 64 25" aria-hidden="true"><path d="M${sets[index].replaceAll(' ',' L')}" fill="none" stroke="currentColor" stroke-width="1.3"/></svg>`;}
function miniChart(preset,cls='preset-chart'){return `<svg class="${cls}" viewBox="0 0 74 44" aria-hidden="true"><path d="M2 1v39h70 M2 25h70" stroke="#e9ede2" stroke-width=".7" fill="none"/><polyline points="${preset?.points||STRATEGIES[0].points}" fill="none" stroke="${preset?.outlook==='Bearish'?'#b58a6e':'#719b62'}" stroke-width="1.8" stroke-linejoin="round"/></svg>`;}

function formatTime(value){return value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Asia/Kolkata'})+' IST':'Timestamp unavailable';}
function feedStatus(){
  if(live.busy)return 'Loading market data';
  if(!live.client)return 'Connect to load actual prices';
  if(live.error)return 'Feed interrupted · last snapshot';
  if(live.marketStatus==='closed')return 'Market closed · last quoted prices';
  const time=Date.parse(market().asOf||'');
  if(!Number.isFinite(time))return 'Quote time unavailable';
  if(Date.now()-time>90000)return 'Quotes stale · refresh';
  return live.marketStatus==='open'?'Market open · refreshing every 30s':'Market status unknown';
}
function strikeOptions(leg){
  const available=getStrikeOptions(state.marketSymbol,leg.expiry,leg.type);
  const currentListed=available.includes(leg.strike);
  return `${currentListed?'':`<option value="${leg.strike}" selected>${num(leg.strike)} · saved</option>`}${available.map(strike=>`<option value="${strike}" ${strike===leg.strike?'selected':''}>${num(strike)}</option>`).join('')}`;
}
function renderFeedBar(){
  if(getDataMode()==='demo')return `<section class="feed-bar sample-feed"><div><strong>${icon('bulb')}Sample mode</strong><p>Illustrative prices from 26 Oct 2026. These are not market quotes.</p></div><button class="btn small" data-action="market-mode">Use market data ${icon('arrow')}</button></section>`;
  const connected=!!live.client;
  return `<section class="feed-bar ${live.error?'feed-error':''}"><div><strong>${icon(connected?'chain':'chart')}${connected?'Personal Upstox feed':'Actual prices. Your private connection.'}</strong><p>${connected?`${escapeHTML(feedStatus())} · Index snapshot: ${escapeHTML(formatTime(market().asOf))}`:'Free Upstox Analytics Token required. No account? You can still explore clearly labeled sample strategies.'}</p>${live.error?`<p class="form-error">${escapeHTML(live.error)}</p>`:''}</div><div class="feed-actions">${connected?`<button class="btn small" data-action="refresh-feed" ${live.busy?'disabled':''}>${icon('reset')}Refresh</button><button class="text-btn" data-action="disconnect-feed">Disconnect</button>`:`<button class="btn small primary" data-action="connect-feed">${icon('chain')}Connect market data</button><button class="text-btn" data-action="sample-mode">Explore sample</button>`}</div></section>${connected?`<section class="mtm-card" id="market-mtm">${renderMtm()}</section>`:''}`;
}
function renderMtm(){
  if(!state.legs.some(l=>l.enabled))return `<div><span class="eyebrow">MARKET P&amp;L · LTP</span><p>Add listed option legs to track their actual last-traded-price P&amp;L.</p></div><strong>—</strong>`;
  const result=markToMarket(legs(),live.quotes,{asOf:new Date().toISOString(),marketStatus:live.error?'unknown':live.marketStatus});
  const unavailable=result.legs.filter(l=>l.status==='missing'||l.status==='stale'||l.status==='expired');
  return `<div><span class="eyebrow">MARKET P&amp;L · LAST TRADED PRICE</span><p>${result.complete?`${live.marketStatus==='closed'?'Market closed · ':''}Snapshot: ${escapeHTML(formatTime(result.oldestQuoteAt))} · Last trade: ${escapeHTML(formatTime(result.oldestLastTradedAt))}`:`${unavailable.length} leg${unavailable.length===1?'':'s'} without a usable mark. ${expiredUnsettled()?'Expired contracts need settlement values.':'Missing or stale quotes are not replaced with model prices.'}`}</p><small>Entry premiums and quantities stay fixed. LTP is not a guaranteed execution price.</small></div><strong class="${result.total>0?'positive':result.total<0?'negative':''}">${money(result.total,true)}</strong>`;
}
function connectModal(){
  openModal('Connect your market data.','A free, personal read-only Upstox connection for NIFTY, BANKNIFTY and SENSEX.',`<form id="market-data-form"><div class="connection-guide"><p><strong>1.</strong> Create or sign in to your Upstox account.</p><p><strong>2.</strong> Open <a href="https://account.upstox.com/developer/apps" target="_blank" rel="noopener noreferrer">Developer Apps → Analytics</a> and generate your free Analytics Token.</p><p><strong>3.</strong> Paste that token below. It is used only for read-only market requests.</p><a href="https://upstox.com/developer/api-documentation/analytics-token/" target="_blank" rel="noopener noreferrer">Read the official token guide ${icon('external')}</a></div><div class="field"><label for="feed-token">Personal Analytics Token</label><input id="feed-token" name="token" class="input" type="password" autocomplete="off" spellcheck="false" autocapitalize="none" maxlength="8192" required placeholder="Paste your read-only Analytics Token"></div><p class="connection-security">${icon('lock')}Kept in memory for this tab only. Sent directly to api.upstox.com; never saved, exported, logged, or uploaded to GitHub. Refreshing this page disconnects it.</p><p class="valuation-caption">A free broker account is still required. This is not an anonymous public data feed. Connecting opens a fresh market workspace; saved positions remain in your library.</p><div class="form-error" id="connection-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">Connect read-only feed ${icon('arrow')}</button></div></form>`);
}
async function connectFeed(form){
  const submit=$('button[type="submit"]',form),error=$('#connection-error'),attempt=++live.connectAttempt;
  submit.disabled=true;error.textContent='Checking your private market-data connection…';
  let candidate;
  try{
    candidate=createUpstoxClient({token:form.elements.token.value});
    form.elements.token.value='';
    const indices=await candidate.getIndices();
    if(attempt!==live.connectAttempt||!form.isConnected)return;
    if(!Number.isFinite(indices[state.marketSymbol]?.spot))throw new Error('No index quote was returned for the selected market. Try again later.');
    live.controller?.abort();live.client=candidate;live.error='';live.quotes={};
    setDataMode('live');applyIndexQuotes(indices);live.valuationAt=new Date().toISOString();
    Object.assign(state,{legs:[],name:'Bull call spread',preset:'bull-call',expiry:'',positionId:null,notes:'',multiplier:1,dirty:false});
    closeModal();resetScenario();render();await loadMarket({preserve:false});
  }catch(cause){candidate=null;if(error.isConnected)error.textContent=cause.message;if(submit.isConnected)submit.disabled=false;}
}
async function loadMarket({preserve=true}={}){
  if(!live.client)return connectModal();
  live.controller?.abort();const controller=new AbortController(),generation=++live.generation,symbol=state.marketSymbol,client=live.client;
  live.controller=controller;live.busy=true;live.error='';render();
  try{
    const [indices,contracts,status]=await Promise.all([client.getIndices({signal:controller.signal}),client.getContracts(symbol,{signal:controller.signal}),client.getMarketStatus(symbol==='SENSEX'?'BSE':'NSE',{signal:controller.signal})]);
    if(generation!==live.generation||symbol!==state.marketSymbol||getDataMode()!=='live'||(typeof client!=='undefined'&&client!==live.client))return;
    applyIndexQuotes(indices);setContracts(symbol,contracts);selectMarketExpiries(symbol);live.marketStatus=status;
    if(!Number.isFinite(market().spot)||market().quoteAvailable===false)throw new Error('The selected index quote is unavailable. Last-known values have not been refreshed.');
    if(!EXPIRIES.length)throw new Error('No active option expiries were returned for this index.');
    if(!preserve||!state.expiry)state.expiry=EXPIRIES[0].value;
    if(EXPIRIES.some(e=>e.value===state.expiry)){
      const chain=await client.getChain(symbol,state.expiry,{signal:controller.signal});
      if(generation!==live.generation||symbol!==state.marketSymbol||getDataMode()!=='live'||(typeof client!=='undefined'&&client!==live.client))return;
      setChain(chain);live.receivedAt=chain.receivedAt;
      if(!preserve){try{state.legs=makeStrategy(state.preset||'bull-call',market(),state.expiry);}catch(error){state.legs=[];state.preset=null;state.name='Untitled strategy';toast(error.message,true);}}
    }
    live.valuationAt=new Date().toISOString();
    if(!preserve||!Number.isFinite(state.scenario.spot))resetScenario();
    await refreshQuotes({generation,signal:controller.signal,quiet:true});
    if(generation!==live.generation||client!==live.client||getDataMode()!=='live')return;
    live.busy=false;persistWorkspace();render();
  }catch(error){if(generation!==live.generation||client!==live.client||getDataMode()!=='live'||error.code==='ABORTED')return;live.busy=false;live.error=error.message;if(error.code==='AUTH')live.client=null;render();}
}
async function refreshQuotes({generation=live.generation,signal,quiet=false}={}){
  if(!live.client||getDataMode()!=='live')return;
  const ids=[...new Set(state.legs.filter(l=>l.enabled&&l.contractId).map(l=>l.contractId))],client=live.client,sequence=++live.quoteRequest;
  if(!ids.length)return;
  try{const quotes=await client.getQuotes(ids,{signal});if(generation!==live.generation||client!==live.client||sequence!==live.quoteRequest||getDataMode()!=='live')return;Object.assign(live.quotes,quotes);live.valuationAt=new Date().toISOString();if(!quiet)updateAnalysis();}
  catch(error){if(error.code==='ABORTED'||generation!==live.generation||client!==live.client||sequence!==live.quoteRequest||getDataMode()!=='live')return;live.error=error.message;if(!quiet)render();else throw error;}
}
function disconnectFeed(){live.connectAttempt++;live.controller?.abort();live.generation++;live.client=null;live.quotes={};live.error='';live.busy=false;live.marketStatus='unknown';setDataMode('live');resetScenario();render();toast('Market data disconnected. Your saved entries are unchanged.');}
function openSample(){live.connectAttempt++;live.controller?.abort();live.generation++;live.client=null;live.quotes={};live.error='';live.busy=false;setDataMode('demo');Object.assign(state,{expiry:EXPIRIES[0].value,name:'Bull call spread',preset:'bull-call',legs:makeStrategy('bull-call',market(),EXPIRIES[0].value),positionId:null,notes:'',multiplier:1,dirty:false});resetScenario();persistWorkspace();render();toast('Sample mode — prices are illustrative.');}
function openMarketMode(){live.connectAttempt++;live.controller?.abort();live.generation++;live.busy=false;setDataMode('live');Object.assign(state,{expiry:'',legs:[],preset:null,name:'Untitled strategy',positionId:null,notes:'',multiplier:1,dirty:false});resetScenario();if(live.client)loadMarket({preserve:false});else render();}
function aboutModal(){openModal('Know where your prices come from.','Market marks and model projections are different views.',`<div class="modal-message"><p><strong>Market mode:</strong> connects directly to your personal Upstox Analytics Token. NIFTY, BANKNIFTY and SENSEX contracts, expiries, lot sizes and premiums come from that feed. A free Upstox account is required.</p><p style="margin-top:12px"><strong>Market P&amp;L:</strong> uses the last traded prices of the exact saved contracts, keeping entry premiums and unit quantities fixed. Closed, stale, unavailable and expired quotes are identified. LTP is not an executable bid/ask.</p><p style="margin-top:12px"><strong>Model scenarios:</strong> Black–Scholes estimates at the displayed valuation clock. Greeks and future prices remain estimates; missing IV or unresolved expired legs disable the model.</p><p style="margin-top:12px"><strong>Sample mode:</strong> uses only the clearly labeled 26 Oct 2026 illustrations. Existing sample positions are preserved as samples.</p></div><div class="modal-actions"><button class="btn" data-action="connect-feed">Connect feed</button><button class="btn primary" data-action="close-modal">Got it</button></div>`);}

function render(){
  const labels={builder:'Strategy builder',positions:'My positions',chain:'Option chain',learn:'Learn options'};
  $('#app').innerHTML=`
  <aside class="sidebar" aria-label="Main navigation">
    <a class="brand" href="#builder" data-view="builder" aria-label="Folio home"><span class="brand-symbol"><svg viewBox="0 0 28 28" fill="none" aria-hidden="true"><path d="M5 23V13h4v10 M13 18V8h4v10 M21 12V3h3v9" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><path d="m5 8 6-5" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></span><span class="brand-word">folio<span>.</span></span></a>
    <div class="brand-caption">A LITTLE CLARITY. A BETTER EDGE.</div>
    <div class="nav-label">YOUR WORKSPACE</div>
    <nav>${[['builder','layers','Strategy builder'],['positions','bookmark','My positions'],['chain','grid','Option chain'],['learn','book','Learn options']].map(([view,glyph,label])=>`<button class="nav-item ${state.view===view?'active':''}" data-view="${view}" ${state.view===view?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span>${view==='positions'?`<span class="nav-count">${library.length}</span>`:''}</button>`).join('')}</nav>
    <div class="sidebar-bottom"><div class="learn-card">${icon('sparkle')}<h3>Big ideas.<br>Zero paywalls.</h3><p>Good tools should be<br>for everyone. Including you.</p><button data-view="learn">Get to know your options ${icon('arrow')}</button></div><div class="sidebar-user"><div class="avatar">Y</div><div><strong>Your personal workspace</strong><small>Saved in this browser.</small></div>${icon('shield')}</div></div>
  </aside><div class="mobile-overlay" data-action="menu-close"></div>
  <div class="main-shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb"><span>Workspace</span>${icon('chevron')}<strong>${labels[state.view]}</strong></div><div class="topbar-actions"><span class="demo-indicator"><i class="dot"></i>${getDataMode()==='demo'?'Sample workspace':live.client?'Personal market feed':'Market data not connected'}</span><span class="top-date">${new Date(valuationDate()).toLocaleDateString('en-IN',{weekday:'short',day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Kolkata'})}</span><button class="icon-btn" data-action="about" aria-label="About market data">${icon('help')}</button></div></header>
  <div class="market-strip" aria-label="${getDataMode()==='demo'?'Sample market snapshot':'Market quotes'}">${MARKETS.map((m,i)=>`<div class="ticker"><div><div class="ticker-label">${m.symbol==='NIFTY'?'NIFTY 50':m.symbol==='BANKNIFTY'?'BANK NIFTY':'SENSEX'}</div><div class="ticker-numbers numeric">${num(m.spot,2)}<span class="ticker-change ${m.changePercent<0?'down':'up'}">${Number.isFinite(m.changePercent)?`${m.changePercent>=0?'+':''}${num(m.changePercent,2)}%`: "Not connected"} ${Number.isFinite(m.changePercent)?icon('arrowUp'):''}</span></div></div>${sparkline(i)}</div>${i<2?'<div class="market-divider"></div>':''}`).join('')}<div class="market-status"><i class="dot"></i>${getDataMode()==='demo'?'Sample data · 26 Oct 2026':feedStatus()}</div></div>
  <main class="main-content">${state.view==='builder'?renderBuilder():state.view==='positions'?renderPositions():state.view==='chain'?renderChain():renderLearn()}${renderFooter()}</main></div>`;
  bindChart();
}
function pageHeading(title,subtitle,eyebrow,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function instrumentBar(){const m=market();return `<div class="instrument-bar"><div class="instrument-icon">${icon('chart')}</div><div class="instrument-select"><label class="visually-hidden" for="market-select">Underlying instrument</label><select id="market-select" data-change="market">${MARKETS.map(entry=>`<option ${entry.symbol===m.symbol?'selected':''}>${entry.symbol}</option>`).join('')}</select><div class="instrument-price numeric">${num(m.spot,2)}<small>${Number.isFinite(m.change)?`${m.change>=0?'+':''}${num(m.change,2)} (${num(m.changePercent,2)}%)`:'Connect for quotes'}</small></div></div>${sparkline(MARKETS.indexOf(m))}<div class="instrument-separator"></div><div class="instrument-field"><label for="expiry-select">Expiry</label><select id="expiry-select" data-change="expiry" ${!EXPIRIES.length||live.busy?'disabled':''}>${expiryOptions(state.expiry)}</select></div><div class="instrument-field"><label>Lot size</label><strong>${m.lotSize?`${m.lotSize} units`:'Per contract'}</strong></div><div class="instrument-info"><span>Explore without limits.</span><button class="badge gray" data-action="about">${getDataMode()==='demo'?'SAMPLE DATA':live.client?'UPSTOX FEED':'NOT CONNECTED'} ${info('View source, quote status and pricing assumptions.')}</button></div></div>`;}
function renderBuilder(){const a=analysis();return `${pageHeading('Strategy builder','A clearer view of every possible outcome.','YOUR OPTIONS. UNDERSTOOD.',`<div class="free-label">${icon('leaf')}Powerful tools. Always free.</div><button class="btn" data-view="learn">${icon('book')}<span>Quick guide</span></button><button class="btn" data-view="positions">${icon('bookmark')}<span>My positions</span></button>`)}<div id="feed-state">${renderFeedBar()}</div>${instrumentBar()}<div class="workspace"><div class="left-column">${renderLegs(a)}<div class="insight-card"><div class="insight-icon">${icon('bulb')}</div><div><strong>A small insight, a better perspective.</strong><p id="insight-text">${insightText(a)}</p></div></div></div><div class="right-column"><div class="metrics" id="metrics">${renderMetrics(a)}</div><section class="card chart-card" aria-label="Strategy analysis"><div class="analysis-tabs" role="tablist" aria-label="Analysis views">${[['payoff','chart','Payoff chart'],['table','table','P&L table'],['greeks','greek','Greeks']].map(([tab,glyph,label])=>`<button class="analysis-tab ${state.tab===tab?'active':''}" data-tab="${tab}" role="tab" aria-selected="${state.tab===tab}">${icon(glyph)}${label}</button>`).join('')}<div class="analysis-tools"><button class="icon-btn" data-action="settings" aria-label="Calculation settings">${icon('sliders')}</button><button class="icon-btn" data-action="export-csv" aria-label="Export payoff table as CSV">${icon('download')}</button></div></div><div id="analysis-content">${renderAnalysis(a)}</div>${renderScenario(a)}</section></div></div>${renderPresets()}`;}
function insightText(a){if(!state.legs.some(l=>l.enabled))return 'Add your first option leg to start seeing how your idea behaves.';if(a.mixedExpiry)return 'Your legs have different expiries. Analysis values the position at the first expiry, keeping time value on later legs.';if(a.maxLoss===Infinity)return 'This strategy has unlimited loss potential. A protective option leg can help define your downside.';if(a.maxProfit===Infinity)return 'Your upside is uncapped. Explore the target date to see how time and volatility affect the journey.';return `Your risk is defined at ${money(a.maxLoss)}. Move the scenario sliders to explore what happens before expiry.`;}
function renderLegs(a){const preset=STRATEGIES.find(p=>p.id===state.preset);return `<section class="card" aria-label="Strategy legs"><div class="card-heading"><h2>Your strategy ${state.dirty?'<i class="unsaved-dot" title="Unsaved changes"></i>':''}</h2><button class="text-btn" data-action="new">${icon('plus')}New strategy</button></div><div class="strategy-description"><div class="strategy-name-line"><label class="visually-hidden" for="strategy-name">Strategy name</label><input id="strategy-name" maxlength="80" value="${escapeHTML(state.name)}" data-input="name" placeholder="Name your strategy">${icon('edit')}</div><div class="strategy-tags"><span>${state.legs.filter(l=>l.enabled).length} active legs</span><i class="dot"></i><span class="outlook">${icon(preset?.outlook==='Bearish'?'chart':'arrowUp')}${escapeHTML(preset?.outlook||'Custom strategy')}</span><i class="dot"></i><span>${a.maxLoss===Infinity?'Open risk':'Defined risk'}</span></div></div><div class="legs-container">${state.legs.length?`<table class="legs-table"><colgroup>${'<col>'.repeat(6)}</colgroup><thead><tr><th>Side</th><th>Strike</th><th>Type</th><th>Lots</th><th>Premium ₹</th><th></th></tr></thead><tbody>${state.legs.map((leg,index)=>`<tr class="${leg.enabled?'':'leg-disabled'}"><td><select class="leg-input leg-side ${leg.side}" data-leg="${escapeHTML(leg.id)}" data-field="side" aria-label="Leg ${index+1} buy or sell"><option value="buy" ${leg.side==='buy'?'selected':''}>BUY</option><option value="sell" ${leg.side==='sell'?'selected':''}>SELL</option></select></td><td><select class="leg-input numeric strike-select" data-leg="${escapeHTML(leg.id)}" data-field="strike" aria-label="Leg ${index+1} strike">${strikeOptions(leg)}</select></td><td><select class="leg-input" data-leg="${escapeHTML(leg.id)}" data-field="type" aria-label="Leg ${index+1} option type"><option ${leg.type==='CE'?'selected':''}>CE</option><option ${leg.type==='PE'?'selected':''}>PE</option></select></td><td><input class="leg-input numeric" type="number" min="1" max="${Math.floor(100/state.multiplier)}" step="1" value="${leg.lots}" data-leg="${escapeHTML(leg.id)}" data-field="lots" aria-label="Leg ${index+1} lots"></td><td><input class="leg-input numeric" type="number" min="0" max="10000000" step="0.05" value="${leg.premium.toFixed(2)}" data-leg="${escapeHTML(leg.id)}" data-field="premium" aria-label="Leg ${index+1} premium"></td><td><button class="remove-leg" data-remove="${escapeHTML(leg.id)}" aria-label="Remove leg ${index+1}">${icon('trash')}</button></td></tr><tr class="leg-expiry"><td colspan="3"><label><input type="checkbox" data-leg="${escapeHTML(leg.id)}" data-field="enabled" ${leg.enabled?'checked':''} aria-label="Include leg ${index+1} in analysis"><select data-leg="${escapeHTML(leg.id)}" data-field="expiry" aria-label="Leg ${index+1} expiry">${expiryOptions(leg.expiry,true)}</select><span>· IV</span><input type="number" data-leg="${escapeHTML(leg.id)}" data-field="iv" value="${leg.iv??''}" placeholder="IV" min="0.1" max="300" step="0.1" aria-label="Leg ${index+1} implied volatility" style="width:31px;border:0;background:none;color:inherit;padding:0;font-size:8px;text-align:right">%</label></td><td colspan="3" class="leg-qty">${num(Math.abs(legUnits(leg,market().lotSize||1))*state.multiplier)} units</td></tr>`).join('')}</tbody></table>`:'<div class="empty-legs">Every idea starts with a first leg.<br>Add an option or pick a strategy below.</div>'}</div><div class="add-leg-row"><button class="add-leg-btn" data-action="add-leg" ${state.legs.length>=24||live.busy?'disabled':''}>${icon('plus')}Add a leg</button><button class="chain-btn" data-view="chain">Option chain ${icon('arrow')}</button></div><div class="strategy-bottom"><div class="strategy-total"><div><span>Net premium <span id="premium-direction">${a.netPremium>=0?'received':'paid'}</span></span><strong id="net-premium">${money(Math.abs(a.netPremium))}</strong><small>excl. charges</small></div><div><span>Multiplier</span><div class="quantity-stepper"><button data-multiplier="-1" aria-label="Decrease strategy multiplier" ${state.multiplier<=1?'disabled':''}>−</button><span>${state.multiplier}×</span><button data-multiplier="1" aria-label="Increase strategy multiplier" ${state.multiplier>=10||state.legs.some(l=>l.lots*(state.multiplier+1)>100)?'disabled':''}>+</button></div></div></div><button class="btn primary save-btn" data-action="save" ${!state.legs.length?'disabled':''}>${icon('bookmark')}Save position ${icon('arrow')}</button><div class="save-note">${icon('lock')}Your ideas, saved on this device.</div></div></section>`;}
function renderMetrics(a){if(!state.legs.length)return ['Max profit','Max loss','Breakeven','Model profit probability'].map(label=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">—</div><div class="metric-caption">Add option legs</div></div>`).join('');const breakeven=a.breakevens.length?a.breakevens.map(value=>num(value,0)).join(' / '):'—';return `<div class="metric"><div class="metric-label">Max profit ${info('Maximum theoretical profit at analysis expiry, excluding charges.')}</div><div class="metric-value positive">${money(a.maxProfit)}</div><div class="metric-caption">${a.maxProfit===Infinity?'Uncapped upside':'At expiry'}</div></div><div class="metric"><div class="metric-label">Max loss ${info('Maximum theoretical loss across nonnegative underlying prices. Does not represent broker margin.')}</div><div class="metric-value negative">${money(a.maxLoss)}</div><div class="metric-caption">${a.maxLoss===Infinity?'Unlimited risk':'Defined downside'}</div></div><div class="metric"><div class="metric-label">Breakeven ${info('Underlying price where analysis-expiry P&L is zero, excluding charges.')}</div><div class="metric-value small">${breakeven}</div><div class="metric-caption">${a.breakevens.length===1?`${((a.breakevens[0]/market().spot-1)*100)>=0?'+':''}${num((a.breakevens[0]/market().spot-1)*100,2)}% from spot`:a.breakevens.length>1?'Lower / upper price':'No crossing found'}</div></div><div class="metric"><div class="metric-label">Model probability ${info('Risk-neutral lognormal model estimate using the displayed IV estimates; not a forecast or guarantee.')}</div><div class="metric-value">${num(a.pop,1)}<span style="font-size:12px;font-weight:500">%</span></div><div class="metric-caption">Theoretical estimate</div></div>`;}
function renderAnalysis(a){if(state.tab==='table'&&state.tableMode==='legs')return renderPnlTable(a);if(!modelAvailable())return `<div class="chart-empty">${expiredUnsettled()?'Expired contracts need a settlement price before current analysis.':state.legs.length?'Connect fresh market quotes and provide each leg’s IV to calculate model scenarios.':'Connect market data, then choose listed option contracts.'}</div>`;return state.tab==='table'?renderPnlTable(a):state.tab==='greeks'?renderGreeks(a):renderChart(a);}
function chartBounds(a){const m=market();const strikes=state.legs.filter(l=>l.enabled).map(l=>l.strike);const buffer=m.spot*.009;const span=m.spot*.027;const low=Math.max(.01,Math.min(m.spot-span,state.scenario.spot-buffer,...strikes.map(k=>k-buffer)));const high=Math.max(m.spot+span,state.scenario.spot+buffer,...strikes.map(k=>k+buffer));return {low,high};}
function renderChart(a){
  if(!state.legs.some(l=>l.enabled))return '<div class="chart-empty">Add or enable a leg to see your payoff.</div>';
  const {low,high}=chartBounds(a);const width=Math.max(325,Math.round((document.querySelector('.chart-card')?.clientWidth)||(window.innerWidth>880?(window.innerWidth-650)*.9:window.innerWidth>620?window.innerWidth-220:window.innerWidth-32)));const w=width,h=292,left=48,right=w-19,top=31,bottom=247;
  const xs=[...new Set([...Array.from({length:151},(_,i)=>low+(high-low)*i/150),...state.legs.filter(l=>l.enabled).map(l=>l.strike).filter(x=>x>=low&&x<=high),...a.breakevens.filter(x=>x>=low&&x<=high)])].sort((x,y)=>x-y);
  const points=xs.map(x=>({x,e:terminalPayoff(x,a),t:targetPayoff(x)}));let minY=Math.min(0,...points.map(p=>Math.min(p.e,p.t))),maxY=Math.max(0,...points.map(p=>Math.max(p.e,p.t)));const spread=Math.max(maxY-minY,100);minY-=spread*.18;maxY+=spread*.2;
  const xScale=x=>left+(x-low)/(high-low)*(right-left);const yScale=y=>bottom-(y-minY)/(maxY-minY)*(bottom-top);const zero=yScale(0);
  const line=key=>points.map((p,i)=>`${i?'L':'M'}${xScale(p.x).toFixed(2)},${yScale(p[key]).toFixed(2)}`).join(' ');const expiryLine=line('e');const area=`${expiryLine} L${right},${zero} L${left},${zero} Z`;
  const xTicks=Array.from({length:5},(_,i)=>low+(high-low)*i/4);const yTicks=Array.from({length:5},(_,i)=>minY+(maxY-minY)*i/4);const spotX=xScale(market().spot);const labelWidth=92;const spotLabelX=clamp(spotX-labelWidth/2,left,right-labelWidth);
  return `<div class="chart-topline"><div class="chart-title">The shape of your strategy <span>· ${formatDate(a.analysisExpiry||state.expiry,false)} expiry</span></div><div class="chart-legends"><span class="legend"><i class="legend-line"></i>${a.mixedExpiry?'First expiry':'At expiry'}</span><span class="legend"><i class="legend-line target"></i>Target date</span></div></div><div class="payoff-wrap"><svg class="payoff-svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Interactive strategy payoff chart. Green is profit and red is loss. Expiry payoff and theoretical target-date payoff are plotted against underlying price." data-low="${low}" data-high="${high}" data-left="${left}" data-right="${right}" data-width="${w}" data-height="${h}" data-min-y="${minY}" data-max-y="${maxY}"><defs><linearGradient id="profit-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b4d6a4" stop-opacity=".31"/><stop offset="100%" stop-color="#d2e5c7" stop-opacity=".11"/></linearGradient><linearGradient id="loss-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#eac9be" stop-opacity=".12"/><stop offset="100%" stop-color="#e6beb1" stop-opacity=".28"/></linearGradient><clipPath id="positive-clip"><rect x="${left}" y="${top}" width="${right-left}" height="${Math.max(0,zero-top)}"/></clipPath><clipPath id="negative-clip"><rect x="${left}" y="${zero}" width="${right-left}" height="${Math.max(0,bottom-zero)}"/></clipPath></defs>${yTicks.map(y=>`<line x1="${left}" y1="${yScale(y)}" x2="${right}" y2="${yScale(y)}" stroke="#eaf0e4" stroke-width=".8" stroke-dasharray="3 4"/><text class="chart-axis" x="${left-8}" y="${yScale(y)+3}" text-anchor="end">${Math.abs(y)>=1000?`${(y/1000).toFixed(1)}k`:num(y)}</text>`).join('')}${xTicks.map(x=>`<line x1="${xScale(x)}" y1="${top}" x2="${xScale(x)}" y2="${bottom}" stroke="#f1f3ec" stroke-width=".7"/><text class="chart-axis" x="${xScale(x)}" y="${bottom+18}" text-anchor="middle">${num(x)}</text>`).join('')}<text class="chart-axis-title" x="${left}" y="16">P&amp;L (₹)</text><path d="${area}" fill="url(#profit-fill)" clip-path="url(#positive-clip)"/><path d="${area}" fill="url(#loss-fill)" clip-path="url(#negative-clip)"/><line x1="${left}" y1="${zero}" x2="${right}" y2="${zero}" stroke="#cbd4c1" stroke-width=".9"/><path d="${expiryLine}" stroke="#598d57" stroke-width="2" fill="none" clip-path="url(#positive-clip)"/><path d="${expiryLine}" stroke="#ce8f76" stroke-width="2" fill="none" clip-path="url(#negative-clip)"/><path d="${line('t')}" stroke="#aaa1bc" stroke-width="1.6" stroke-dasharray="5 4" fill="none"/><line x1="${spotX}" y1="${top}" x2="${spotX}" y2="${bottom}" stroke="#adba9a" stroke-width="1" stroke-dasharray="3 4"/><rect x="${spotLabelX}" y="6" width="${labelWidth}" height="18" rx="4" fill="#f0f4e8"/><text x="${spotLabelX+labelWidth/2}" y="18" text-anchor="middle" style="font-size:8px;fill:#82926f;font-family:'DM Sans',sans-serif">Spot ${num(market().spot,2)}</text><circle cx="${xScale(state.scenario.spot)}" cy="${yScale(targetPayoff(state.scenario.spot))}" r="3" fill="#aaa1bc" stroke="white" stroke-width="1.5"/><g class="hover-elements" visibility="hidden"><line class="hover-line" x1="0" y1="${top}" x2="0" y2="${bottom}" stroke="#819a6b" stroke-dasharray="2 3"/><circle class="hover-dot" r="4" fill="#598d57" stroke="white" stroke-width="2"/></g><text class="chart-axis-title" x="${(left+right)/2}" y="287" text-anchor="middle">Underlying price at expiry</text></svg><div class="chart-tooltip hidden"></div></div><div class="chart-bottomline"><span>${icon('search')}Hover over the chart to explore outcomes</span><span>${icon('shield')}Reward / risk: ${a.rewardRisk===Infinity?'Unlimited':num(a.rewardRisk,2)+'×'}</span></div>`;
}
function renderScenario(a){const m=market();const max=targetDays();return `<div class="scenario-area"><div class="scenario-heading"><h3>${icon('sliders')}What if the market moves?</h3><button class="text-btn" data-action="reset-scenario">${icon('reset')}Reset</button></div><div class="scenario-controls"><div class="slider-control"><div class="slider-title"><label for="scenario-spot">Target price</label><span id="spot-change">${scenarioChange()}</span></div><div class="slider-value"><input id="scenario-spot" data-scenario="spot" type="number" min="${(m.spot||1)*.5}" max="${(m.spot||1)*1.5}" step="0.05" value="${Number.isFinite(state.scenario.spot)?state.scenario.spot.toFixed(2):''}" ${!Number.isFinite(m.spot)?'disabled':''} aria-label="Scenario target underlying price"></div><input class="range" aria-label="Adjust target price" data-range="spot" type="range" min="${(m.spot||1)*.9}" max="${(m.spot||1)*1.1}" step="1" value="${state.scenario.spot||1}" ${!Number.isFinite(m.spot)?'disabled':''}><div class="range-labels"><span>−10%</span><span>+10%</span></div></div><div class="slider-control"><div class="slider-title"><label for="scenario-days">Days forward</label>${info('Calendar days from the displayed valuation time. Sample mode uses 26 Oct 2026; the market feed uses the current clock.')}</div><div class="slider-value"><input id="scenario-days" class="days-input" type="number" min="0" max="${max}" step="0.1" data-scenario="days" value="${numDays(state.scenario.days)}"><span id="days-caption">${Math.abs(state.scenario.days-max)<.001?'at expiry':'days'}</span></div><input class="range" aria-label="Adjust days forward" data-range="days" type="range" min="0" max="${max}" step="${max/100||.01}" value="${state.scenario.days}"><div class="range-labels"><span>Today</span><span>Expiry</span></div></div><div class="slider-control"><div class="slider-title"><label for="scenario-iv">IV change</label>${info('Added to each option leg’s implied volatility, in percentage points. Volatility is floored at zero.')}</div><div class="slider-value"><input id="scenario-iv" class="iv-input" data-scenario="iv" type="number" min="-10" max="30" step="0.5" value="${state.scenario.iv}"><span>points</span></div><input class="range" aria-label="Adjust implied volatility" data-range="iv" type="range" min="-10" max="30" step="0.5" value="${state.scenario.iv}"><div class="range-labels"><span>−10</span><span>+30</span></div></div></div><div class="scenario-result" id="scenario-result">${renderScenarioResult(a)}</div></div>`;}
function scenarioChange(){if(!Number.isFinite(state.scenario.spot)||!Number.isFinite(market().spot))return '—';const change=(state.scenario.spot/market().spot-1)*100;return `${change>=0?'+':''}${num(change,2)}%`;}
function numDays(days){return Number(days.toFixed(1));}
function renderScenarioResult(a){const p=targetPayoff(state.scenario.spot);if(!modelAvailable())return `<p>Model scenarios require a connected index quote and IV for each active leg.</p><div><span class="result-label">PROJECTED MODEL P&amp;L</span><strong class="result-number neutral">—</strong></div>`;return `<p>If ${market().symbol} is at <strong>${num(state.scenario.spot,2)}</strong><br>in <strong>${numDays(state.scenario.days)} days</strong>, with IV <strong>${state.scenario.iv>=0?'+':''}${state.scenario.iv.toFixed(1)} points</strong></p><div><span class="result-label">PROJECTED MODEL P&amp;L</span><strong class="result-number ${Math.abs(p)<1?'neutral':p>0?'positive':'negative'}">${money(p,true)}</strong></div>`;}
function tableRows(a){const m=market();return Array.from({length:13},(_,i)=>{const spot=m.spot*(1+(i-6)*.005);return {spot,change:(i-6)*.5,expiry:terminalPayoff(spot,a),target:targetPayoff(spot)};});}
function renderPnlTable(a){
  const switcher=`<div class="table-switcher" role="group" aria-label="P&L table detail"><button class="${state.tableMode==='outcomes'?'active':''}" data-table-mode="outcomes" aria-pressed="${state.tableMode==='outcomes'}">Market outcomes</button><button class="${state.tableMode==='legs'?'active':''}" data-table-mode="legs" aria-pressed="${state.tableMode==='legs'}">Option values</button></div>`;
  if(state.tableMode==='legs'){
    const mtm=getDataMode()==='live'?markToMarket(legs(),live.quotes,{asOf:new Date().toISOString(),marketStatus:live.error?'unknown':live.marketStatus}):null;
    return `<div class="data-panel pnl-panel">${switcher}<p class="valuation-caption">Target: ${market().symbol} ${num(state.scenario.spot,2)} · ${numDays(state.scenario.days)} days forward · IV ${state.scenario.iv>=0?'+':''}${state.scenario.iv.toFixed(1)} points</p><table class="data-table leg-values"><thead><tr><th>Option leg</th><th>Entry ₹</th><th>Market LTP ₹</th><th>Model target ₹</th><th>Market P&amp;L</th><th>Model P&amp;L</th></tr></thead><tbody>${legs().map(leg=>{
      const years=Math.max(0,expiryYears(leg.expiry,valuationDate())-state.scenario.days/365);
      const settled=Date.parse(leg.expiresAt||leg.expiry+'T10:00:00Z')<=Date.parse(valuationDate())&&Number.isFinite(leg.settlementPrice);
      const value=settled?leg.settlementPrice:Number.isFinite(leg.iv)&&Number.isFinite(state.scenario.spot)&&!expiredUnsettled()?optionPrice(state.scenario.spot,leg.strike,years,Math.max(0,leg.iv+state.scenario.iv)/100,state.rate,leg.type):null;
      const pnl=leg.enabled&&value!==null?(value-leg.premium)*legUnits(leg,market().lotSize||1):leg.enabled?null:0;
      const mark=mtm?.legs.find(row=>row.id===leg.id);
      return `<tr class="${leg.enabled?'':'leg-disabled'}"><td><strong>${leg.side==='buy'?'B':'S'} ${num(leg.strike)} ${leg.type}</strong><br><span class="tiny">${formatDate(leg.expiry,false)} · ${num(Math.abs(legUnits(leg,market().lotSize||1)))} units${mark?' · '+mark.status:''}</span></td><td>${num(leg.premium,2)}</td><td>${num(mark?.price,2)}</td><td>${num(value,2)}</td><td class="${mark?.pl>=0?'positive':'negative'}">${money(mark?.pl,true)}</td><td class="${pnl>=0?'positive':'negative'}">${money(pnl,true)}</td></tr>`;
    }).join('')}<tr class="spot-row"><td colspan="4"><strong>Net P&amp;L</strong></td><td><strong>${money(mtm?.total,true)}</strong></td><td><strong>${money(targetPayoff(state.scenario.spot),true)}</strong></td></tr></tbody></table><p class="valuation-caption">Entry is fixed. Market P&amp;L uses provider LTP; model P&amp;L uses Black–Scholes. Premiums are per unit; P&amp;L includes signed quantities. Charges excluded.</p></div>`;
  }
  return `<div class="data-panel pnl-panel">${switcher}<table class="data-table"><thead><tr><th>Underlying price</th><th>Move</th><th>${a.mixedExpiry?'First expiry':'At expiry'}</th><th>On target date</th></tr></thead><tbody>${tableRows(a).map(row=>`<tr class="${row.change===0?'spot-row':''}"><td>${num(row.spot,2)} ${row.change===0?'<span class="tiny">SPOT</span>':''}</td><td class="muted">${row.change>0?'+':''}${row.change.toFixed(1)}%</td><td class="${row.expiry>=0?'positive':'negative'}">${money(row.expiry,true)}</td><td class="${row.target>=0?'positive':'negative'}">${money(row.target,true)}</td></tr>`).join('')}</tbody></table></div>`;
}
function renderGreeks(a){const items=[['Δ','Delta',a.delta,'Estimated P&L change (₹) for a 1-point rise in the underlying.'],['Γ','Gamma',a.gamma,'Change in position delta for a 1-point rise in the underlying.'],['Θ','Theta',a.theta,'Estimated P&L change (₹) as one calendar day passes.'],['ν','Vega',a.vega,'Estimated P&L change (₹) for a 1 percentage point increase in IV.']];return `<div class="data-panel"><div class="greek-grid">${items.map(([symbol,label,value,description])=>`<div class="greek-card"><h4><span class="greek-symbol">${symbol}</span>${label}</h4><strong>${value>0?'+':''}${num(value,label==='Gamma'?4:2)}</strong><p>${description}</p></div>`).join('')}</div><p class="greek-note">Position Greeks include active quantities and the multiplier. Values use the demo spot and each leg’s base IV. Scenario changes affect the target-date payoff, while these Greeks describe the starting position.</p></div>`;}
function renderPresets(){const matches=STRATEGIES.filter(p=>state.filter==='All'||p.outlook===state.filter);const shown=state.filter==='All'?[STRATEGIES[0],STRATEGIES[2],STRATEGIES[6],STRATEGIES[8]]:matches;return `<section class="presets-section"><div class="section-title-row"><h2>A head start for your next idea <span>Start with a strategy. Make it yours.</span></h2><div class="filter-tabs" role="group" aria-label="Strategy outlook filter">${['All','Bullish','Bearish','Neutral','Volatile'].map(filter=>`<button class="filter-tab ${state.filter===filter?'active':''}" data-filter="${filter}" aria-pressed="${state.filter===filter}">${filter}</button>`).join('')}</div></div><div class="preset-grid">${shown.map(p=>`<button class="preset-card ${state.preset===p.id?'selected':''}" data-preset="${p.id}">${miniChart(p)}<span class="preset-arrow">${icon('arrowUp')}</span><h3>${p.name}</h3><p>${p.description}</p><span class="badge ${p.outlook==='Bearish'?'red':p.outlook==='Volatile'?'purple':'green'}">${p.outlook==='Bullish'?'↗ ':p.outlook==='Bearish'?'↘ ':p.outlook==='Neutral'?'↔ ':'⤢ '}${p.outlook}</span></button>`).join('')}</div></section>`;}
function renderPositions(){const filtered=library.filter(p=>`${p.name} ${p.marketSymbol} ${p.notes}`.toLowerCase().includes(state.search.toLowerCase()));return `${pageHeading('Good ideas deserve a second look.','Your saved strategies, ready whenever you are.','YOUR PERSONAL STRATEGY LIBRARY',`<button class="btn primary" data-view="builder">${icon('plus')}<span>Build a strategy</span></button>`)}<div class="library-tools"><div class="search-input">${icon('search')}<label class="visually-hidden" for="position-search">Search positions</label><input class="input" id="position-search" placeholder="Search your positions…" value="${escapeHTML(state.search)}" data-input="search"></div><button class="btn small" data-action="backup" ${!library.length?'disabled':''}>${icon('download')}Export backup</button><button class="btn small import-btn" data-action="import">${icon('upload')}Import backup</button><input type="file" id="import-file" accept="application/json,.json" hidden></div>${storageError?`<div class="model-notice" style="margin:0 0 20px;color:var(--red)">${escapeHTML(storageError)} Your stored library has been left untouched. You can continue analyzing strategies.</div>`:''}<div id="position-results">${positionResults(filtered)}</div><p class="library-notice">${icon('lock')}Positions are stored in this browser on this device. Export a backup before clearing browser data or moving to another device. Opening a saved position lets you edit and analyze it.</p>`;}
function positionResults(filtered){return filtered.length?`<div class="position-grid">${filtered.map(positionCard).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">${icon(state.search?'search':'bookmark')}</div><h2>${state.search?'No matching ideas just yet.':'Your next good idea belongs here.'}</h2><p>${state.search?'Try another name, market, or a word from your notes.':'Build a strategy and save it. Come back, revisit your assumptions, and keep exploring.'}</p>${!state.search?`<button class="btn primary" data-view="builder">${icon('plus')}Build your first strategy</button>`:''}</div>`;}
function positionPreview(position,a,m){
  if(position.dataMode==='live'&&a.mixedExpiry&&!Number.isFinite(m.spot))return '<span class="valuation-caption">Open with market data for mixed-expiry analysis.</span>';const active=position.legs.filter(l=>l.enabled);m={...m,spot:Number.isFinite(m.spot)?m.spot:(active[0]?.strike||1)};
  const min=Math.max(0,Math.min(m.spot*.97,...active.map(l=>l.strike-m.spot*.01)));
  const max=Math.max(m.spot*1.03,...active.map(l=>l.strike+m.spot*.01));
  const points=Array.from({length:101},(_,i)=>{const x=min+(max-min)*i/100;return {x,y:a.mixedExpiry?scenarioPayoff(position.legs,x,a.daysToExpiry,0,m.lotSize||1,position.rate,position.dataMode==='live'?new Date().toISOString():DEMO_DATE):expiryPayoff(position.legs,x,m.lotSize||1)};});
  const low=Math.min(0,...points.map(p=>p.y)),high=Math.max(0,...points.map(p=>p.y));
  const y=value=>65-(value-low)/(high-low||1)*54;
  const d=points.map((point,i)=>`${i?'L':'M'}${(6+i*1.68).toFixed(1)},${y(point.y).toFixed(1)}`).join(' ');
  return `<svg viewBox="0 0 180 75" role="img" aria-label="Saved position payoff preview"><path d="M6 ${y(0)}H174" stroke="#dce5d3" stroke-width=".6"/><path d="${d}" stroke="#719b62" stroke-width="1.5" fill="none"/></svg>`;
}
function positionCard(p){const sourceMarket=(p.dataMode==='live'?MARKETS:DEMO_MARKETS).find(m=>m.symbol===p.marketSymbol),stamp=Date.parse(sourceMarket.asOf||''),usable=p.dataMode!=='live'||(getDataMode()==='live'&&live.client&&!live.error&&sourceMarket.quoteAvailable!==false&&Number.isFinite(stamp)&&(live.marketStatus==='closed'||Date.now()-stamp<=90000)&&p.legs.filter(l=>l.enabled).every(l=>Number.isFinite(l.iv)&&Date.parse(l.expiresAt||l.expiry+'T10:00:00Z')>Date.now())),m={...sourceMarket,spot:usable?sourceMarket.spot:null};const a=analyzeStrategy(p.legs,Number.isFinite(m.spot)?m.spot:(p.legs[0]?.strike||1),m.lotSize||1,m.iv||14.2,p.rate,p.dataMode==='live'?new Date().toISOString():DEMO_DATE);if(p.dataMode==='live'){a.pop=null;if(a.mixedExpiry&&!Number.isFinite(m.spot)){a.maxProfit=null;a.maxLoss=null;}}return `<article class="card position-card"><div class="position-top"><div><h3>${escapeHTML(p.name)}</h3><p>${m.symbol} · ${formatDate(p.expiry,false)} · ${p.legs.length} legs</p></div><span class="badge ${p.dataMode==='live'?'green':'gray'}">${p.dataMode==='live'?'Market entry':'Sample'}</span></div><div class="position-chart">${positionPreview(p,a,m)}</div><div class="position-stats"><div><span>Max profit</span><strong class="positive">${money(a.maxProfit)}</strong></div><div><span>Max loss</span><strong class="negative">${money(a.maxLoss)}</strong></div><div><span>Net premium</span><strong>${money(Math.abs(a.netPremium))} <small class="muted" style="font-size:8px">${a.netPremium>=0?'CR':'DR'}</small></strong></div><div><span>Profit probability</span><strong>${Number.isFinite(a.pop)?num(a.pop,1)+'%':'—'}</strong></div></div>${p.notes?`<p class="position-notes">${escapeHTML(p.notes)}</p>`:''}<div class="position-bottom"><button class="btn small primary" data-open="${escapeHTML(p.id)}">Open & analyze ${icon('arrow')}</button><button class="icon-btn" data-delete="${escapeHTML(p.id)}" aria-label="Delete ${escapeHTML(p.name)}">${icon('trash')}</button></div><div class="position-saved">Saved ${new Date(p.updatedAt).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})} · Model values, excluding charges</div></article>`;}
function renderChain(){
  const m=market(),chain=getChain(m,state.expiry),atm=Number.isFinite(m.spot)?Math.floor(m.spot/m.step)*m.step:null;
  const actions=(row,type)=>{const quote=row[type==='CE'?'call':'put'],disabled=!Number.isFinite(quote?.premium)||live.busy;return `<div class="chain-actions"><button data-chain-strike="${row.strike}" data-chain-type="${type}" data-chain-side="buy" aria-label="Buy ${row.strike} ${type==='CE'?'call':'put'}" ${disabled?'disabled':''}>B</button><button class="sell" data-chain-strike="${row.strike}" data-chain-type="${type}" data-chain-side="sell" aria-label="Sell ${row.strike} ${type==='CE'?'call':'put'}" ${disabled?'disabled':''}>S</button></div>`;};
  return `${pageHeading('One market. So many possibilities.','Choose listed contracts and add a leg directly to your strategy.','THE BUILDING BLOCKS',`<button class="btn primary" data-view="builder">${icon('layers')}<span>Strategy · ${state.legs.length} legs</span></button>`)}<div id="feed-state">${renderFeedBar()}</div>${instrumentBar()}<section class="chain-layout"><div class="card"><div class="chain-summary"><div><h2>${m.name} option chain</h2><p>Click B to buy or S to sell. Each selection captures a new hypothetical entry.</p></div><span class="badge green">${num(m.spot,2)} SPOT</span></div>${chain.length?`<div class="chain-table-wrap"><table class="data-table chain-table"><thead><tr><th colspan="4" class="chain-side">CALLS</th><th class="strike-cell" rowspan="2">Strike</th><th colspan="4" class="chain-side put-side">PUTS</th></tr><tr><th>Add leg</th><th>OI (lakh)</th><th>IV %</th><th>LTP ₹</th><th>LTP ₹</th><th>IV %</th><th>OI (lakh)</th><th>Add leg</th></tr></thead><tbody>${chain.map(row=>`<tr class="${row.strike===atm?'atm-row':''}"><td>${actions(row,'CE')}</td><td class="muted">${Number.isFinite(row.call?.oi)?num(row.call.oi/100000,2):'—'}</td><td class="muted">${num(row.call?.iv,1)}</td><td>${num(row.call?.premium,2)}</td><td class="strike-cell">${num(row.strike)}${row.strike===atm?'<br><span class="tiny">NEAR SPOT</span>':''}</td><td>${num(row.put?.premium,2)}</td><td class="muted">${num(row.put?.iv,1)}</td><td class="muted">${Number.isFinite(row.put?.oi)?num(row.put.oi/100000,2):'—'}</td><td>${actions(row,'PE')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="chart-empty">Connect your personal market feed to load listed contracts and actual prices.</div>'}<p class="chain-footnote">${getDataMode()==='demo'?'Sample option prices, IV, open interest, lot sizes and expiries are illustrative.':'Personal Upstox option-chain response. Shows up to 25 strikes near spot; each leg’s strike dropdown includes every listed strike. Missing quotes stay blank. Chain responses do not provide trade timestamps; exact contract quote times appear in Market P&L. No data is redistributed from a shared account.'}</p></div></section>`;
}
function renderLearn(){return `${pageHeading('A little knowledge goes a long way.','Understand the building blocks. Build with more confidence.','THE FOLIO FIELD GUIDE',`<button class="btn primary" data-view="builder">${icon('layers')}<span>Try the builder</span></button>`)}<div class="guide-hero"><div><h2>Your options.<br>A little better understood.</h2><p>No jargon wall. No subscription. Just the essentials to help you see what a strategy does before you commit to an idea.</p></div><div class="guide-art">${icon('leaf')}</div></div><div class="guide-grid">${[
['01 / THE BASICS','A call, a put, a possibility.','A call gives its holder the right to buy at the strike price. A put gives the right to sell. Buyers pay a premium; sellers receive it and take on the corresponding obligation. CE and PE refer to European-style calls and puts.','Start with one leg','long-call'],
['02 / THE PAYOFF','See the whole shape.','The solid line shows the strategy’s P&L at expiry. Green areas show profit; warm red areas show loss. Breakevens are where the line crosses zero. The dashed line models value on your chosen target date.','Explore a defined-risk spread','bull-call'],
['03 / THE GREEKS','Four ways your strategy can change.','Delta measures sensitivity to price. Gamma measures how delta changes. Theta estimates the effect of a passing day. Vega estimates sensitivity to a one percentage point change in implied volatility. They are local model estimates, not promises.','Look at the Greeks','greeks'],
['04 / THE SCENARIOS','Make room for “what if”.','Change the target price, days forward, and IV to see how theoretical P&L behaves. A correct directional view alone may not produce a profit: entry premium, time decay, and changing volatility also matter.','Explore a long straddle','long-straddle'],
['05 / DEFINED RISK','Give your idea some boundaries.','A spread combines bought and sold options to change its payoff. A bull call spread caps potential upside in exchange for reducing the initial debit. Some short-option strategies have unlimited loss potential; the builder marks this explicitly.','Explore an iron condor','iron-condor'],
['06 / YOUR WORKSPACE','Let your ideas evolve.','Save a position with your thesis and notes, then reopen it to change assumptions. Updates can replace the saved position or become a separate idea. Your library lives on this browser, so export a JSON backup to keep a portable copy.','Visit your saved positions','positions']
].map(([n,title,body,label,action])=>`<article class="card guide-card"><div class="guide-number">${n}</div><h3>${title}</h3><p>${body}</p><button class="text-btn" data-guide="${action}">${label} ${icon('arrow')}</button></article>`).join('')}</div><div class="model-notice"><strong>How the model works.</strong> Folio uses Black–Scholes for European options, with no dividends and a default 6% annual risk-free rate. Market mode uses the current valuation clock; sample mode is fixed at 26 Oct 2026 at 12:00 IST. Actual LTP-based market P&L is displayed separately from this model. Premiums are per unit; P&L uses each leg’s saved contract quantity. A free personal Upstox account and Analytics Token are required for the market feed. Brokerage, taxes, slippage, margin, and execution are not included. For different expiries, analysis uses the first expiry and preserves later legs’ time value. Profit probability is a risk-neutral lognormal estimate, not a forecast. Learn more from the Options Industry Council: <a href="https://www.optionseducation.org/advancedconcepts/black-scholes-formula" target="_blank" rel="noopener noreferrer">option pricing ${icon('external')}</a> and <a href="https://www.optionseducation.org/advancedconcepts/understanding-options-greeks" target="_blank" rel="noopener noreferrer">the Greeks</a>.</div>`;}
function renderFooter(){return `<footer class="footer"><p>${getDataMode()==='demo'?'Sample data, clearly separate from market quotes.':'Market data connects directly to your personal Upstox feed.'} LTP P&L and model scenarios exclude charges. No orders are placed.</p><span class="footer-brand">folio. &nbsp; Free to find your edge.</span></footer>`;}

function updateAnalysis(){const a=analysis();if($('#market-mtm'))$('#market-mtm').innerHTML=renderMtm();if($('#metrics'))$('#metrics').innerHTML=renderMetrics(a);if($('#analysis-content'))$('#analysis-content').innerHTML=renderAnalysis(a);if($('#scenario-result'))$('#scenario-result').innerHTML=renderScenarioResult(a);if($('#net-premium'))$('#net-premium').textContent=money(Math.abs(a.netPremium));if($('#premium-direction'))$('#premium-direction').textContent=a.netPremium>=0?'received':'paid';if($('#insight-text'))$('#insight-text').textContent=insightText(a);bindChart();}
function syncScenario(except=''){for(const key of ['spot','days','iv']){const value=state.scenario[key];const numeric=$(`[data-scenario="${key}"]`),range=$(`[data-range="${key}"]`);if(numeric&&except!==`numeric-${key}`)numeric.value=key==='spot'?(Number.isFinite(value)?value.toFixed(2):''):key==='days'?numDays(value):value;if(range&&except!==`range-${key}`)range.value=value;}if($('#spot-change'))$('#spot-change').textContent=scenarioChange();if($('#days-caption'))$('#days-caption').textContent=Math.abs(state.scenario.days-targetDays())<.001?'at expiry':'days';updateAnalysis();}
function bindChart(){const svg=$('.payoff-svg');if(!svg)return;const tooltip=$('.chart-tooltip');const hover=$('.hover-elements',svg);const a=analysis();svg.addEventListener('pointermove',event=>{const box=svg.getBoundingClientRect(),w=Number(svg.dataset.width),left=Number(svg.dataset.left),right=Number(svg.dataset.right);const pixel=clamp((event.clientX-box.left)/box.width*w,left,right),spot=Number(svg.dataset.low)+(pixel-left)/(right-left)*(Number(svg.dataset.high)-Number(svg.dataset.low));const expiry=terminalPayoff(spot,a),target=targetPayoff(spot);const y=247-(expiry-Number(svg.dataset.minY))/(Number(svg.dataset.maxY)-Number(svg.dataset.minY))*(247-31);hover.setAttribute('visibility','visible');const line=$('.hover-line',svg);line.setAttribute('x1',pixel);line.setAttribute('x2',pixel);const dot=$('.hover-dot',svg);dot.setAttribute('cx',pixel);dot.setAttribute('cy',y);tooltip.innerHTML=`<strong>${market().symbol} ${num(spot,2)}</strong><p>At expiry <span>${money(expiry,true)}</span></p><p>Target date <span>${money(target,true)}</span></p>`;tooltip.classList.remove('hidden');tooltip.style.left=`${clamp(event.clientX-box.left+12,5,box.width-162)}px`;tooltip.style.top=`${clamp(event.clientY-box.top-45,26,box.height-83)}px`;});svg.addEventListener('pointerleave',()=>{hover.setAttribute('visibility','hidden');tooltip.classList.add('hidden');});}
function setView(view){if(!['builder','positions','chain','learn'].includes(view))return;state.view=view;history.replaceState(null,'',`#${view}`);render();window.scrollTo({top:0,behavior:'instant'});}
function resetScenario(){state.scenario={spot:market().spot,days:0,iv:0};}
function applyPreset(presetId){
  if(getDataMode()==='live'&&!live.client){connectModal();return;}
  if(live.busy){toast('Wait for the contract list to load.');return;}
  const p=STRATEGIES.find(p=>p.id===presetId);if(!p)return;
  let next;try{next=makeStrategy(p.id,market(),state.expiry);}catch(error){toast(error.message,true);return;}
  Object.assign(state,{name:p.name,preset:p.id,legs:next,positionId:null,notes:'',multiplier:1});
  resetScenario();markDirty();setView('builder');if(getDataMode()==='live')refreshQuotes();toast(`${p.name} is ready to explore`);
}
function loadPosition(id){const p=library.find(p=>p.id===id);if(!p)return;live.connectAttempt++;live.controller?.abort();live.generation++;live.busy=false;live.error='';const wanted=p.dataMode==='live'?'live':'demo';if(wanted!==getDataMode())setDataMode(wanted);if(wanted==='demo'){live.client=null;live.quotes={};}Object.assign(state,{marketSymbol:p.marketSymbol,expiry:p.expiry,name:p.name,legs:structuredClone(p.legs),rate:p.rate??.06,positionId:p.id,notes:p.notes||'',multiplier:1,preset:STRATEGIES.find(s=>s.name.toLowerCase()===p.name.toLowerCase())?.id||null,dirty:false});resetScenario();persistWorkspace();setView('builder');if(getDataMode()==='live'&&live.client)loadMarket({preserve:true});toast('Saved position opened');}
function toast(message,error=false){const el=$('#toast');el.innerHTML=`${icon(error?'help':'check')}<span>${escapeHTML(message)}</span>`;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4200);}
let modalCleanup=null;
function openModal(title,subtitle,body,{wide=false}={}){if($('#market-data-form'))live.connectAttempt++;modalCleanup?.();modalCleanup=null;const previous=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-heading"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';const handler=e=>{if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const list=$$('button:not(:disabled),input:not([type=hidden]),textarea,select,a[href]',$('.modal'));if(!list.length)return;if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus();}}};document.addEventListener('keydown',handler);modalCleanup=()=>{document.removeEventListener('keydown',handler);previous?.isConnected&&previous.focus();};setTimeout(()=>($('.modal [autofocus]')||$('.modal input')||$('.modal .icon-btn'))?.focus(),20);}
function closeModal(){if($('#market-data-form'))live.connectAttempt++;$('#modal-root').innerHTML='';document.body.style.overflow='';modalCleanup?.();modalCleanup=null;}
function saveModal(){if(storageError){toast(storageError,true);return;}const existing=library.find(p=>p.id===state.positionId);const a=analysis();openModal(existing?'Keep your idea up to date.':'An idea worth keeping.','Save your position and a little context for your future self.',`<form id="save-form"><div class="modal-summary"><strong>${market().symbol} · ${state.legs.length} legs</strong><span>${formatDate(state.expiry,false)} expiry</span></div><div class="field"><label for="save-name">Position name</label><input class="input" id="save-name" name="name" maxlength="80" required value="${escapeHTML(state.name)}" autofocus></div><div class="field"><label for="save-notes">Your thesis or notes <span class="muted">(optional)</span></label><textarea class="input" id="save-notes" name="notes" maxlength="2000" placeholder="What’s the idea? What would change your view?">${escapeHTML(state.notes)}</textarea></div>${existing?'<label class="modal-checkbox"><input type="checkbox" name="copy">Save as a new position instead of updating this one</label>':''}<div class="form-error" id="save-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${icon('bookmark')}${existing?'Save changes':'Save position'}</button></div></form>`);}
function commitSave(form){const data=new FormData(form);const existing=library.find(p=>p.id===state.positionId);const copy=data.get('copy')==='on';const position={...snapshot(),id:existing&&!copy?existing.id:uid(),name:String(data.get('name')||'').trim(),notes:String(data.get('notes')||'').trim(),createdAt:existing&&!copy?existing.createdAt:new Date().toISOString()};try{const valid=validatePosition(position);const next=existing&&!copy?library.map(p=>p.id===existing.id?valid:p):[valid,...library];writePositions(next);library=next;state.positionId=valid.id;state.name=valid.name;state.notes=valid.notes;state.dirty=false;persistWorkspace();closeModal();render();toast(existing&&!copy?'Position updated. Your idea is safe.':'Position saved. Revisit it in My positions.');}catch(error){$('#save-error').textContent=error.message;}}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCsv(){if(!modelAvailable()){toast('Connect market data before exporting model outcomes.',true);return;}const a=analysis();const rows=[['Underlying price','Move %','Analysis expiry P&L INR','Target date P&L INR'],...tableRows(a).map(r=>[r.spot.toFixed(2),r.change.toFixed(1),r.expiry.toFixed(2),r.target.toFixed(2)])];download(`folio-${state.marketSymbol.toLowerCase()}-payoff.csv`,rows.map(r=>r.join(',')).join('\n'),'text/csv;charset=utf-8');toast('Payoff table exported');}
function deleteModal(id){const position=library.find(p=>p.id===id);if(!position)return;openModal('Make room for new ideas.','',`<p class="modal-message">Delete <strong>${escapeHTML(position.name)}</strong> from your saved positions? This removes the saved copy from this browser.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Keep position</button><button class="btn danger" data-confirm-delete="${escapeHTML(id)}">Delete position</button></div>`);}
function newModal(){openModal('A fresh perspective.','Start an empty strategy. Your saved positions stay in your library.',`<p class="modal-message">Your current workspace will be replaced. Save it first if you’d like to keep this version.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Keep exploring</button><button class="btn primary" data-action="confirm-new">Start fresh ${icon('arrow')}</button></div>`);}
function settingsModal(){openModal('A little more control.','These settings apply to the theoretical valuation model.',`<form id="settings-form"><div class="field"><label for="risk-rate">Annual risk-free rate (%)</label><input class="input" type="number" id="risk-rate" name="rate" min="0" max="30" step="0.1" value="${state.rate*100}" required></div><p class="modal-message" style="font-size:10px;margin-top:16px">Valuation time: ${escapeHTML(formatTime(valuationDate()))}. European options, zero dividend yield, and no transaction costs. Existing entry premiums stay fixed when the rate changes.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Apply settings</button></div></form>`);}
function recoveryModal(){openModal('Restore your position library.','Your backup is valid. Your current browser library could not be read.',`<p class="modal-message">Keep a copy of the original site data before replacing it with the <strong>${pendingRecovery.length} positions</strong> in this backup. Your current strategy workspace will stay available.</p><button class="btn small" style="margin-top:17px" data-action="raw-backup">${icon('download')}Download original site data</button><div class="modal-actions"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-recovery">Restore backup</button></div>`);}
document.addEventListener('click',event=>{
  const button=event.target.closest('button,a[data-view]');if(!button){if(event.target.classList.contains('modal-backdrop'))closeModal();if(event.target.matches('.mobile-overlay')){$('.sidebar')?.classList.remove('open');$('.mobile-overlay')?.classList.remove('open');}return;}
  if(button.disabled)return;
  const d=button.dataset;
  if(d.view){event.preventDefault();setView(d.view);return;}
  if(d.tab){state.tab=d.tab;$$('.analysis-tab').forEach(b=>{b.classList.toggle('active',b.dataset.tab===d.tab);b.setAttribute('aria-selected',String(b.dataset.tab===d.tab));});updateAnalysis();return;}
  if(d.tableMode){state.tableMode=d.tableMode;updateAnalysis();return;}
  if(d.filter){state.filter=d.filter;const section=$('.presets-section');section.outerHTML=renderPresets();return;}
  if(d.preset){applyPreset(d.preset);return;}
  if(d.remove){state.legs=state.legs.filter(l=>l.id!==d.remove);state.preset=null;state.scenario.days=Math.min(state.scenario.days,targetDays());markDirty();render();return;}
  if(d.multiplier){const next=state.multiplier+Number(d.multiplier);if(next>=1&&next<=10&&state.legs.every(l=>l.lots*next<=100)){state.multiplier=next;markDirty();render();}return;}
  if(d.open){loadPosition(d.open);return;}
  if(d.delete){deleteModal(d.delete);return;}
  if(d.confirmDelete){try{const next=library.filter(p=>p.id!==d.confirmDelete);writePositions(next);library=next;if(state.positionId===d.confirmDelete){state.positionId=null;persistWorkspace();}closeModal();render();toast('Saved position deleted');}catch(error){toast(error.message,true);}return;}
  if(d.guide){if(d.guide==='positions')setView('positions');else if(d.guide==='greeks'){state.tab='greeks';setView('builder');}else applyPreset(d.guide);return;}
  if(d.chainStrike){if(state.legs.length>=24){toast('You can explore up to 24 legs in one strategy.',true);return;}let leg;try{leg=makeLeg(market(),state.expiry,{strike:Number(d.chainStrike),type:d.chainType,side:d.chainSide});}catch(error){toast(error.message,true);return;}state.legs.push(leg);state.preset=null;markDirty();render();if(getDataMode()==='live')refreshQuotes();toast(`${leg.side==='buy'?'Buy':'Sell'} ${num(leg.strike)} ${leg.type} added to your strategy`);return;}
  switch(d.action){
    case 'save':saveModal();break;
    case 'new':newModal();break;
    case 'confirm-new':live.connectAttempt++;live.controller?.abort();live.generation++;live.busy=false;state.name='Untitled strategy';state.legs=[];state.preset=null;state.positionId=null;state.notes='';state.multiplier=1;resetScenario();markDirty();closeModal();render();break;
    case 'add-leg':if(state.legs.length<24){if(getDataMode()==='live'&&!live.client){connectModal();break;}try{state.legs.push(makeLeg(market(),state.expiry));state.preset=null;markDirty();render();if(getDataMode()==='live')refreshQuotes();}catch(error){toast(error.message,true);}}break;
    case 'reset-scenario':resetScenario();syncScenario();break;
    case 'export-csv':exportCsv();break;
    case 'close-modal':closeModal();break;
    case 'settings':settingsModal();break;
    case 'about':aboutModal();break;
    case 'connect-feed':connectModal();break;
    case 'refresh-feed':if(live.client)loadMarket({preserve:true});else connectModal();break;
    case 'disconnect-feed':disconnectFeed();break;
    case 'sample-mode':openSample();break;
    case 'market-mode':openMarketMode();break;
    case 'learn-from-modal':closeModal();setView('learn');break;
    case 'backup':download(`folio-positions-${new Date().toISOString().slice(0,10)}.json`,makeBackup(library),'application/json');toast('Your positions backup is ready');break;
    case 'import':$('#import-file').click();break;
    case 'raw-backup':try{download('folio-original-site-data.txt',localStorage.getItem('folio.positions.v1')||'No stored data','text/plain');}catch(error){toast('Browser storage is unavailable. Enable it and try again.',true);}break;
    case 'confirm-recovery':try{writePositions(pendingRecovery);library=pendingRecovery;pendingRecovery=null;storageError='';closeModal();render();toast('Position library restored from your backup');}catch(error){toast(error.message,true);}break;
    case 'menu':$('.sidebar').classList.toggle('open');$('.mobile-overlay').classList.toggle('open');break;
  }
});
document.addEventListener('input',event=>{
  const el=event.target;
  if(el.dataset.input==='name'){state.name=el.value;markDirty();return;}
  if(el.dataset.input==='search'){state.search=el.value;$('#position-results').innerHTML=positionResults(library.filter(p=>`${p.name} ${p.marketSymbol} ${p.notes}`.toLowerCase().includes(state.search.toLowerCase())));return;}
  if(el.dataset.leg&&['lots','premium','iv'].includes(el.dataset.field)){
    const leg=state.legs.find(l=>l.id===el.dataset.leg),field=el.dataset.field,value=Number(el.value);
    if(!leg||el.value===''||!Number.isFinite(value))return;
    const bounds={strike:[1,1e7],lots:[1,Math.floor(100/state.multiplier)],premium:[0,1e7],iv:[.1,300]};
    if(value<bounds[field][0]||value>bounds[field][1]||(field==='lots'&&!Number.isInteger(value)))return;
    leg[field]=value;state.preset=null;
    if(field==='lots')leg.quantityUnits=value*(leg.lotSize||market().lotSize||1);
    if(field==='premium')leg.entryPriceSource='manual';
    if(field==='iv')leg.ivSource='manual';
    markDirty();updateAnalysis();return;
  }
  const key=el.dataset.range||el.dataset.scenario;if(!key)return;
  let value=Number(el.value);if(!Number.isFinite(value)||el.value==='')return;
  const bounds={spot:[market().spot*.5,market().spot*1.5],days:[0,targetDays()],iv:[-10,30]};value=clamp(value,...bounds[key]);state.scenario[key]=value;syncScenario(`${el.dataset.range?'range':'numeric'}-${key}`);
});
document.addEventListener('change',async event=>{
  const el=event.target,d=el.dataset;
  if(d.leg){
    const leg=state.legs.find(l=>l.id===d.leg);if(!leg)return;
    const field=d.field;let value=field==='enabled'?el.checked:['strike','lots','premium','iv'].includes(field)?Number(el.value):el.value;
    if(typeof value==='number'){
      if(!Number.isFinite(value)||el.value==='')value=leg[field];
      if(field==='lots')value=clamp(Math.round(value),1,Math.floor(100/state.multiplier));
      if(field==='premium')value=clamp(value,0,1e7);
      if(field==='iv'&&Number.isFinite(value))value=clamp(value,.1,300);
    }
    if(['strike','type','expiry'].includes(field)){
      const desired={...leg,[field]:value},symbol=state.marketSymbol;
      if(getDataMode()==='live'){
        if(!live.client){connectModal();render();return;}
        const client=live.client,generation=++live.generation;live.controller?.abort();live.controller=new AbortController();live.busy=true;
        try{
          const chain=await client.getChain(symbol,desired.expiry,{signal:live.controller.signal});
          if(generation!==live.generation||symbol!==state.marketSymbol||getDataMode()!=='live'||(typeof client!=='undefined'&&client!==live.client))return;
          setChain(chain);
          const replacement=makeLeg(market(),desired.expiry,{id:leg.id,strike:desired.strike,type:desired.type,side:leg.side,lots:leg.lots,enabled:leg.enabled});
          state.legs=state.legs.map(l=>l.id===leg.id?replacement:l);live.error='';
          toast('Contract changed. New hypothetical entry captured; saved copy stays unchanged until you save.');
        }catch(error){if(error.code!=='ABORTED')toast(error.message,true);}
        finally{if(generation===live.generation)live.busy=false;}
      }else state.legs=state.legs.map(l=>l.id===leg.id?makeLeg(market(),desired.expiry,{...desired,premium:undefined}):l);
    }else{
      leg[field]=value;
      if(field==='lots')leg.quantityUnits=value*(leg.lotSize||market().lotSize||1);
      if(field==='premium')leg.entryPriceSource='manual';
      if(field==='iv')leg.ivSource='manual';
    }
    state.preset=null;state.scenario.days=Math.min(state.scenario.days,targetDays());markDirty();render();
    if(getDataMode()==='live')refreshQuotes();return;
  }
  if(d.change==='market'){
    const previous=state.marketSymbol;state.marketSymbol=el.value;state.positionId=null;state.notes='';state.multiplier=1;
    if(getDataMode()==='live'){
      state.expiry='';state.legs=[];state.preset=state.preset||'bull-call';state.name=STRATEGIES.find(p=>p.id===state.preset)?.name||'Untitled strategy';resetScenario();
      if(live.client)await loadMarket({preserve:false});else{selectMarketExpiries(state.marketSymbol);render();}return;
    }
    if(state.legs.length){if(state.preset)state.legs=makeStrategy(state.preset,market(),state.expiry);else{const prior=MARKETS.find(m=>m.symbol===previous);state.legs=state.legs.map(leg=>makeLeg(market(),leg.expiry,{...leg,strike:Math.max(market().step,Math.round((market().spot+(leg.strike-prior.spot)*market().spot/prior.spot)/market().step)*market().step),iv:market().iv,premium:undefined}));}}
    resetScenario();markDirty();render();toast(`Switched to ${state.marketSymbol}. Sample contracts refreshed.`);return;
  }
  if(d.change==='expiry'){
    const expiry=el.value;
    if(getDataMode()==='live'){
      if(!live.client)return connectModal();
      const symbol=state.marketSymbol,client=live.client,generation=++live.generation;live.controller?.abort();live.controller=new AbortController();live.busy=true;
      try{const chain=await client.getChain(symbol,expiry,{signal:live.controller.signal});if(generation!==live.generation||symbol!==state.marketSymbol||getDataMode()!=='live'||(typeof client!=='undefined'&&client!==live.client))return;setChain(chain);
        const replaced=state.legs.map(leg=>makeLeg(market(),expiry,{id:leg.id,strike:leg.strike,type:leg.type,side:leg.side,lots:leg.lots,enabled:leg.enabled}));state.expiry=expiry;state.legs=replaced;live.error='';
        toast('Expiry changed. New hypothetical entries use the selected contracts’ market premiums.');
      }catch(error){if(error.code!=='ABORTED')toast(error.message,true);}finally{if(generation===live.generation)live.busy=false;}
    }else{state.expiry=expiry;state.legs=state.legs.map(leg=>makeLeg(market(),expiry,{...leg,expiry,premium:undefined}));}
    resetScenario();markDirty();render();if(getDataMode()==='live')refreshQuotes();return;
  }
  if(d.scenario){syncScenario();return;}
  if(el.id==='import-file'){const file=el.files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('Choose a JSON backup smaller than 5 MB.');const imported=parseImport(await file.text());if(storageError){pendingRecovery=imported;recoveryModal();el.value='';return;}const ids=new Set(library.map(p=>p.id));const unique=imported.filter(p=>!ids.has(p.id));const next=[...unique,...library];writePositions(next);library=next;render();toast(`${unique.length} position${unique.length===1?'':'s'} imported${imported.length>unique.length?' · existing copies skipped':''}`);}catch(error){toast(error.message,true);}el.value='';}
});
document.addEventListener('submit',event=>{if(event.target.id==='market-data-form'){event.preventDefault();connectFeed(event.target);return;}if(event.target.id==='save-form'){event.preventDefault();commitSave(event.target);}if(event.target.id==='settings-form'){event.preventDefault();const value=Number(new FormData(event.target).get('rate'));if(!Number.isFinite(value)||value<0||value>30)return;state.rate=value/100;markDirty();closeModal();updateAnalysis();toast('Valuation settings updated');}});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['builder','positions','chain','learn'].includes(view)&&view!==state.view){state.view=view;render();}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.view==='builder'&&state.tab==='payoff')updateAnalysis();},180);});
render();
if(state.view==='builder'&&state.tab==='payoff')requestAnimationFrame(updateAnalysis);
if(storageError)setTimeout(()=>toast(storageError,true),300);

let polling=false;
async function pollMarket(){
  if(polling||live.busy||!live.client||getDataMode()!=='live'||document.hidden)return;
  polling=true;const generation=live.generation,symbol=state.marketSymbol,expiry=state.expiry,client=live.client,sequence=++live.quoteRequest;
  const ids=[...new Set(state.legs.filter(l=>l.enabled&&l.contractId).map(l=>l.contractId))];
  try{
    const [indices,chain,quotes,status]=await Promise.all([client.getIndices(),expiry&&EXPIRIES.some(e=>e.value===expiry)?client.getChain(symbol,expiry):Promise.resolve(null),client.getQuotes(ids),client.getMarketStatus(symbol==='SENSEX'?'BSE':'NSE')]);
    if(generation!==live.generation||symbol!==state.marketSymbol||expiry!==state.expiry||client!==live.client||getDataMode()!=='live')return;
    applyIndexQuotes(indices);if(market().quoteAvailable===false)throw new Error('The selected index quote is unavailable. Last-known values have not been refreshed.');if(chain)setChain(chain);if(sequence===live.quoteRequest)Object.assign(live.quotes,quotes);live.marketStatus=status;live.valuationAt=new Date().toISOString();live.error='';
    $$('.ticker-numbers').forEach((el,i)=>{const m=MARKETS[i];el.innerHTML=`${num(m.spot,2)}<span class="ticker-change ${m.changePercent<0?'down':'up'}">${Number.isFinite(m.changePercent)?`${m.changePercent>=0?'+':''}${num(m.changePercent,2)}%`:'—'}</span>`;});
    const price=$('.instrument-price');if(price)price.innerHTML=`${num(market().spot,2)}<small>${Number.isFinite(market().change)?`${market().change>=0?'+':''}${num(market().change,2)} (${num(market().changePercent,2)}%)`:'Quote unavailable'}</small>`;
    const feed=$('#feed-state');if(feed&&!feed.contains(document.activeElement))feed.innerHTML=renderFeedBar();if($('.market-status'))$('.market-status').innerHTML=`<i class="dot"></i>${escapeHTML(feedStatus())}`;if(state.view==='chain'){const template=document.createElement('template');template.innerHTML=renderChain();const next=template.content.querySelector('.chain-layout');if(next&&$('.chain-layout'))$('.chain-layout').replaceWith(next);}updateAnalysis();
  }catch(error){if(generation!==live.generation||client!==live.client||getDataMode()!=='live')return;live.error=error.message;const feed=$('#feed-state');if(feed)feed.innerHTML=renderFeedBar();updateAnalysis();}
  finally{polling=false;}
}
setInterval(pollMarket,30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollMarket();});
